    long double fi, se;
    Val(long double a=0.0, long double b=0.0): fi(a), se(b) {}
};

Val add_vals(const Val& a, const Val& b) {
    return Val(a.fi + b.fi, a.se + b.se);
}

Val subtract_vals(const Val& a, const Val& b) {
    return Val(a.fi - b.fi, a.se - b.se);
}

Val multiply_val(const Val& a, long double w) {
    return Val(a.fi * w, a.se * w);
}

Val divide_val(const Val& a, long double w) {
    return Val(a.fi / w, a.se / w);
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> probabilities(n);
    for (int i = 0; i < n; ++i) cin >> probabilities[i];

    for (int target = 0; target < n; ++target) {
        vector<Val> dp(1 << n, Val(0.0, 0.0));
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (mask == 0) {
                dp[mask] = Val(1.0, 0.0);
            }
        }
        for (int mask = 1; mask < (1 << n); ++mask) {
            if (mask & (1 << target)) continue;
            Val sum(0.0, 0.0);
            double same_prob = 0.0;
            for (int j = 0; j < n; ++j) {
                if (j != target && (mask & (1 << j))) {
                    same_prob += probabilities[j];
                    sum = add_vals(sum, multiply_val(dp[mask ^ (1 << j)], probabilities[j]));
                }
            }
            dp[mask] = divide_val(sum, 1.0 - same_prob);
        }
        Val total(1.0, 0.0);
        for (int mask = 1; mask < (1 << n); ++mask) {
            if (!(mask & (1 << target))) {
                total = add_vals(total, dp[mask]);
            }
        }
        double alpha = (1.0 - total.se) / total.fi;
        Val bad(0.0, 0.0);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (mask & (1 << target)) continue;
            if (__builtin_popcount(mask) >= k) {
                bad = add_vals(bad, dp[mask]);
            }
        }
        cout << fixed << setprecision(12) << 1.0 - (alpha * bad.fi + bad.se) << (target + 1 == n ? '\n' : ' ');
    }
    return 0;
}
