import java.util.*;
import java.io.*;

public class Main {
    static class Val {
        double fi, se;
        Val(double a, double b) {
            this.fi = a;
            this.se = b;
        }
    }

    static Val add_vals(Val a, Val b) {
        return new Val(a.fi + b.fi, a.se + b.se);
    }

    static Val subtract_vals(Val a, Val b) {
        return new Val(a.fi - b.fi, a.se - b.se);
    }

    static Val multiply_val(Val a, double w) {
        return new Val(a.fi * w, a.se * w);
    }

    static Val divide_val(Val a, double w) {
        return new Val(a.fi / w, a.se / w);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] probabilities = new double[n];
        for (int i = 0; i < n; i++) {
            probabilities[i] = sc.nextDouble();
        }

        for (int target = 0; target < n; target++) {
            Val[] dp = new Val[1 << n];
            for (int mask = 0; mask < (1 << n); mask++) {
                dp[mask] = new Val(0.0, 0.0);
            }
            for (int mask = 0; mask < (1 << n); mask++) {
                if (mask == 0) {
                    dp[mask] = new Val(1.0, 0.0);
                }
            }
            for (int mask = 1; mask < (1 << n); mask++) {
                if ((mask & (1 << target)) != 0) continue;
                Val sum = new Val(0.0, 0.0);
                double same_prob = 0.0;
                for (int j = 0; j < n; j++) {
                    if (j != target && ((mask & (1 << j)) ) != 0) {
                        same_prob += probabilities[j];
                        sum = add_vals(sum, multiply_val(dp[mask ^ (1 << j)], probabilities[j]));
                    }
                }
                double denom = 1.0 - same_prob;
                if (denom == 0) {
                    // To avoid division by zero, continue or handle accordingly
                    continue;
                }
                dp[mask] = divide_val(sum, denom);
            }
            Val total = new Val(1.0, 0.0);
            for (int mask = 1; mask < (1 << n); mask++) {
                if ((mask & (1 << target)) == 0) {
                    total = add_vals(total, dp[mask]);
                }
            }
            double alpha = (1.0 - total.se) / total.fi;
            Val bad = new Val(0.0, 0.0);
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & (1 << target)) != 0) continue;
                if (Integer.bitCount(mask) >= k) {
                    bad = add_vals(bad, dp[mask]);
                }
            }
            double result = 1.0 - (alpha * bad.fi + bad.se);
            System.out.printf(Locale.US, "%.12f%s", result, (target + 1 == n) ? "\n" : " ");
        }
        sc.close();
    }
}
